            let rdSize := returndatasize()
            // If the call failed or returned no data, return an empty string.
            if iszero(and(success, gt(rdSize, 0x3f))) {
                // Return an empty string.
                mstore(result, 0)
                mstore(0x40, add(result, 0x20))
                leave
            }
            // Copy returndata to memory starting at result + 0x20.
            returndatacopy(add(result, 0x20), 0x00, rdSize)
            // Try to ABI decode the string.
            // The offset is at position 0 (first 32 bytes).
            let offset := mload(add(result, 0x20))
            // Check if offset is valid (within returndata bounds).
            if lt(offset, rdSize) {
                // Read the string length.
                let strLen := mload(add(add(result, 0x20), offset))
                // Check if string data fits within returndata.
                let dataStart := add(add(result, 0x20), add(offset, 0x20))
                let dataEnd := add(dataStart, strLen)
                let rdEnd := add(add(result, 0x20), rdSize)
                if iszero(gt(dataEnd, rdEnd)) {
                    // Truncate if necessary.
                    if gt(strLen, limit) {
                        strLen := limit
                    }
                    // Store the string length.
                    mstore(result, strLen)
                    // Move string data in-place (shift left by 0x20 - offset bytes).
                    let dst := add(result, 0x20)
                    let src := add(add(result, 0x20), add(offset, 0x20))
                    // Copy the string bytes.
                    for { let i := 0 } lt(i, strLen) { i := add(i, 0x20) } {
                        mstore(add(dst, i), mload(add(src, i)))
                    }
                    // Zero the trailing bytes.
                    let trailing := and(strLen, 0x1f)
                    if trailing {
                        mstore(add(add(dst, strLen), 0), shl(mul(8, trailing), shr(mul(8, sub(0x20, trailing)), mload(add(add(dst, strLen), 0)))))
                    }
                    // Update free memory pointer.
                    mstore(0x40, add(add(dst, strLen), 0x20))
                    leave
                }
            }
            // Fallback: read returndata as a null-terminated string.
            let strDataStart := add(result, 0x20)
            let strDataLen := rdSize
