                strDataLen := limit
            }
            // Find null terminator.
            let nullPos := strDataLen
            for { let i := 0 } lt(i, strDataLen) { i := add(i, 1) } {
                if iszero(byte(0, mload(add(strDataStart, i)))) {
                    nullPos := i
                    break
                }
            }
            // Store the string length.
            mstore(result, nullPos)
            // Ensure trailing zeros.
            mstore(add(add(strDataStart, nullPos), 0), 0)
            // Update free memory pointer.
