    /// @param data The bytes memory data to be stored in memory.
    /// @return result A bytes32 value representing the pointer (data location in lower bits, length in upper bits).
    function _ptr(bytes memory data) private pure returns (bytes32 result) {
        /// @solidity memory-safe-assembly
        assembly {
            // The pointer encodes: data length in upper 64 bits, data pointer in lower 160 bits.
            let len := mload(data)
            let ptr := add(data, 0x20)
            // Encode the pointer.
            result := or(shl(192, len), ptr)
        }
    }
